def search(x, seq):
    """ Takes in a value x and a sorted sequence seq, and returns the
    position that x should go to such that the sequence remains sorted """
    counter = -1
    for i in seq:
        if len(seq) == 0:
            return 0
        if x <= i:
            counter += 1
            return counter
        elif x > i:
            counter += 1
        else:
            counter += 1
    if x > seq[counter]:
        return counter + 1

